import { beforeEach, describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { ThemeProvider } from '@/contexts/ThemeContext';
import type { CredentialsCatalogue, ConsumerProvider } from '../catalogue';

const sendRequest = vi.fn();
const useCatalogue = vi.fn();
vi.mock('@/contexts/WebSocketContext', () => ({
  useWebSocketActions: () => ({ sendRequest, isReady: true }),
}));
vi.mock('../catalogue', async (importOriginal) => ({
  ...(await importOriginal<typeof import('../catalogue')>()),
  useCredentialsCatalogue: () => useCatalogue(),
}));
vi.mock('sonner', () => ({ toast: { success: vi.fn(), info: vi.fn(), error: vi.fn() } }));

import { CredentialsBrowser } from '../CredentialsBrowser';

const ENDPOINT: ConsumerProvider = {
  id: 'openai_compatible', name: 'Model server', category: 'ai', category_label: 'AI',
  consumer_category: 'ai', color: '', kind: 'apiKey', connected: true,
  endpoints: [{ ref: 'openai_compatible:lab', label: 'Lab', base_url: 'http://gpu:8000', kind: 'generic', model_count: 1 }],
};

function catalogue(providers: ConsumerProvider[] = [ENDPOINT]): CredentialsCatalogue {
  return {
    catalogue: { data: { providers } }, providers, categories: [],
    isLoading: false, isError: false, error: null, refetch: vi.fn(),
  } as unknown as CredentialsCatalogue;
}

beforeEach(() => {
  sendRequest.mockReset().mockResolvedValue({ success: true });
  useCatalogue.mockReset();
});

describe('CredentialsBrowser', () => {
  it('uses its host catalogue without fetching another copy and can manage in Yours', () => {
    const onConnect = vi.fn();
    render(<ThemeProvider><CredentialsBrowser catalogue={catalogue()} onConnect={onConnect} /></ThemeProvider>);
    expect(useCatalogue).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole('radio', { name: /Yours/ }));
    fireEvent.click(screen.getByRole('button', { name: 'Manage Model server' }));
    expect(onConnect).toHaveBeenCalledWith('openai_compatible', 'manage');
    expect(sendRequest).not.toHaveBeenCalled();
  });

  it('hands named-endpoint removal to the panel instead of deleting the family id', async () => {
    const onConnect = vi.fn();
    render(<ThemeProvider><CredentialsBrowser catalogue={catalogue()} onConnect={onConnect} /></ThemeProvider>);
    fireEvent.click(screen.getByRole('button', { name: 'Disconnect Model server' }));
    fireEvent.click(screen.getByRole('button', { name: 'Disconnect' }));
    await waitFor(() => expect(onConnect).toHaveBeenCalledWith('openai_compatible', 'manage'));
    expect(sendRequest).not.toHaveBeenCalled();
  });

  it('offers a retry when no catalogue could be loaded', () => {
    const state = catalogue([]);
    state.catalogue = { ...state.catalogue, data: undefined } as CredentialsCatalogue['catalogue'];
    state.isError = true;
    render(<ThemeProvider><CredentialsBrowser catalogue={state} onConnect={vi.fn()} /></ThemeProvider>);
    expect(screen.getByText("Couldn't load connectors")).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: 'Try again' }));
    expect(state.refetch).toHaveBeenCalledTimes(1);
  });
});

/**
 * ApiKeyPanel for a provider that holds several rows (named OpenAI-compatible
 * endpoints): the form sends every field under its catalogue key, refresh and
 * remove address one endpoint by its reference, and the two requests that
 * probe the server get the probe budget instead of the 30 s default.
 */

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

const sendWs = vi.fn();
const setFieldValue = vi.fn();
const setError = vi.fn();

vi.mock('../../useCredentialPanel', () => ({
  useCredentialPanel: () => ({
    values: {
      openai_compatible_url: 'http://gpu:8000',
      openai_compatible_label: 'Lab',
      openai_compatible_api_key: 'sk-1',
    },
    loading: null,
    error: null,
    stored: false,
    setError,
    form: { setFieldValue },
    actions: { sendWs, validate: vi.fn(), save: vi.fn(), remove: vi.fn() },
  }),
}));

vi.mock('../../../../assets/icons', () => ({ NodeIcon: () => null }));

import ApiKeyPanel from '../ApiKeyPanel';
import { CREDENTIAL_PROBE_REQUEST_TIMEOUT } from '@/contexts/WebSocketContext';
import type { ProviderConfig } from '../../types';

const LAB = {
  ref: 'openai_compatible:lab',
  label: 'Lab',
  base_url: 'http://gpu:8000/v1',
  kind: 'generic',
  model_count: 1,
};

const CONFIG: ProviderConfig = {
  id: 'openai_compatible',
  name: 'OpenAI-compatible',
  category: 'ai',
  categoryLabel: 'AI Models',
  color: '',
  kind: 'apiKey',
  iconRef: 'lucide:Plug',
  fields: [
    { key: 'openai_compatible_url', label: 'Base URL' },
    { key: 'openai_compatible_label', label: 'Label' },
    { key: 'openai_compatible_api_key', label: 'API key', secret: true },
  ],
  stored: true,
  endpoints: [LAB],
};

describe('ApiKeyPanel with named endpoints', () => {
  beforeEach(() => {
    sendWs.mockReset();
    setFieldValue.mockReset();
    setError.mockReset();
  });

  it('adds an endpoint with every field under its catalogue key', async () => {
    sendWs.mockResolvedValue({ valid: true });
    render(<ApiKeyPanel config={CONFIG} visible />);

    await userEvent.click(screen.getByRole('button', { name: 'Add endpoint' }));

    expect(sendWs).toHaveBeenCalledWith(
      'validate_api_key',
      {
        provider: 'openai_compatible',
        api_key: 'http://gpu:8000',
        openai_compatible_label: 'Lab',
        openai_compatible_api_key: 'sk-1',
      },
      CREDENTIAL_PROBE_REQUEST_TIMEOUT,
    );
    expect(setFieldValue.mock.calls).toEqual([
      ['openai_compatible_url', ''],
      ['openai_compatible_label', ''],
      ['openai_compatible_api_key', ''],
    ]);
  });

  it("shows the server's reason when a save is refused and keeps the form", async () => {
    sendWs.mockResolvedValue({ valid: false, message: 'No OpenAI-compatible API answered at http://gpu:8000.' });
    render(<ApiKeyPanel config={CONFIG} visible />);

    await userEvent.click(screen.getByRole('button', { name: 'Add endpoint' }));

    expect(setError).toHaveBeenCalledWith('No OpenAI-compatible API answered at http://gpu:8000.');
    expect(setFieldValue).not.toHaveBeenCalled();
  });

  it('refreshes an endpoint by its reference', async () => {
    sendWs.mockResolvedValue({ valid: true });
    render(<ApiKeyPanel config={CONFIG} visible />);

    await userEvent.click(screen.getByRole('button', { name: 'Refresh Lab' }));

    expect(sendWs).toHaveBeenCalledWith(
      'validate_api_key',
      { provider: 'openai_compatible', api_key: 'http://gpu:8000/v1', ref: 'openai_compatible:lab' },
      CREDENTIAL_PROBE_REQUEST_TIMEOUT,
    );
  });

  it('removes an endpoint by its reference', async () => {
    render(<ApiKeyPanel config={CONFIG} visible />);

    await userEvent.click(screen.getByRole('button', { name: 'Remove Lab' }));

    expect(sendWs).toHaveBeenCalledWith('delete_api_key', { provider: 'openai_compatible:lab' });
  });

  it('gives a probing request longer than the default request timeout', () => {
    expect(CREDENTIAL_PROBE_REQUEST_TIMEOUT).toBeGreaterThan(30_000);
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const mocks = vi.hoisted(() => ({ sendRequest: vi.fn(), ready: true }));
vi.mock('@/contexts/WebSocketContext', () => ({
  useWebSocketActions: () => ({ sendRequest: mocks.sendRequest, isReady: mocks.ready }),
}));

import BrowserLoginBindings from '../BrowserLoginBindings';

const username = `op://${'a'.repeat(26)}/${'b'.repeat(26)}/username`;
const password = `op://${'a'.repeat(26)}/${'b'.repeat(26)}/password`;
const binding = { id: 'login-1', label: 'Account', origin: 'https://accounts.example.com',
  profile_id: 'work', employee_id: 'employee-1', workflow_id: 'workflow-1',
  success_origin: 'https://app.example.com', success_path: '/account', success_selector: '[data-account]' };

function mount(visible = true) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false }, mutations: { retry: false } } });
  const element = (shown: boolean) => <QueryClientProvider client={client}><BrowserLoginBindings visible={shown} profiles={[{ id: 'work', name: 'Work' }]} /></QueryClientProvider>;
  const view = render(element(visible));
  return { client, change: (shown: boolean) => view.rerender(element(shown)) };
}

beforeEach(() => {
  mocks.ready = true;
  mocks.sendRequest.mockReset();
  mocks.sendRequest.mockImplementation(async (command: string) => command === 'browser_credential_bindings_list' ? { bindings: [] } : {});
});

async function fillReferences(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText('Username 1Password reference'), username);
  await user.type(screen.getByLabelText('Password 1Password reference'), password);
}

describe('BrowserLoginBindings', () => {
  it('lists metadata and replaces references without retrieving or prefilling saved credentials', async () => {
    mocks.sendRequest.mockImplementation(async (command: string) => command === 'browser_credential_bindings_list'
      ? { bindings: [{ ...binding, username_reference: 'PRIVATE-REF', password_reference: 'SECRET-CANARY' }] } : {});
    const user = userEvent.setup();
    mount();
    expect(await screen.findByText('Account')).toBeInTheDocument();
    expect(screen.getByText('Profile: Work')).toBeInTheDocument();
    expect(screen.queryByText('SECRET-CANARY')).not.toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: 'Replace Account' }));
    expect(screen.getByLabelText('Username 1Password reference')).toHaveValue('');
    expect(screen.getByLabelText('Password 1Password reference')).toHaveValue('');
    expect(screen.getByRole('button', { name: 'Save website login' })).toBeDisabled();
    await fillReferences(user);
    await user.click(screen.getByRole('button', { name: 'Save website login' }));
    await waitFor(() => expect(mocks.sendRequest).toHaveBeenCalledWith('browser_credential_binding_save', {
      binding_id: 'login-1', label: 'Account', origin: binding.origin, username_reference: username, password_reference: password,
      success_origin: binding.success_origin, success_path: binding.success_path, success_selector: binding.success_selector,
      profile_id: 'work', employee_id: 'employee-1', workflow_id: 'workflow-1',
    }));
    await waitFor(() => expect(screen.queryByLabelText('Password 1Password reference')).not.toBeInTheDocument());
    expect(mocks.sendRequest.mock.calls.every(([command]) => !['get_api_key', 'validate_api_key', 'onepassword_endpoint_validate'].includes(command))).toBe(true);
  });

  it('creates an exact-origin binding with an optional profile and refreshes metadata', async () => {
    const user = userEvent.setup();
    const { client } = mount();
    const invalidate = vi.spyOn(client, 'invalidateQueries');
    await screen.findByText('No website login bindings saved.');
    await user.click(screen.getByRole('button', { name: 'Add website login' }));
    await user.type(screen.getByLabelText('Login label'), '  Work account  ');
    await user.type(screen.getByLabelText('Exact login origin'), binding.origin);
    await fillReferences(user);
    await user.type(screen.getByLabelText('Successful login path'), '/dashboard');
    await user.type(screen.getByLabelText('Successful login selector (optional)'), '#signed-in');
    await user.selectOptions(screen.getByLabelText('Restrict to browser profile (optional)'), 'work');
    await user.click(screen.getByRole('button', { name: 'Save website login' }));
    await waitFor(() => expect(mocks.sendRequest).toHaveBeenCalledWith('browser_credential_binding_save', {
      label: 'Work account', origin: binding.origin, username_reference: username, password_reference: password,
      success_origin: binding.origin, success_path: '/dashboard', success_selector: '#signed-in', profile_id: 'work',
    }));
    expect(invalidate).toHaveBeenCalledWith({ queryKey: ['browserCredentialBindings'] });
    expect(invalidate).toHaveBeenCalledWith({ queryKey: ['credentialCatalogue'] });
  });

  it('requires confirmation before removing a binding and sends only its opaque ID', async () => {
    mocks.sendRequest.mockImplementation(async (command: string) => command === 'browser_credential_bindings_list' ? { bindings: [binding] } : {});
    const user = userEvent.setup();
    mount();
    await user.click(await screen.findByRole('button', { name: 'Remove website login Account' }));
    expect(mocks.sendRequest).not.toHaveBeenCalledWith('browser_credential_binding_delete', expect.anything());
    await user.click(within(screen.getByRole('alertdialog')).getByRole('button', { name: 'Remove login' }));
    await waitFor(() => expect(mocks.sendRequest).toHaveBeenCalledWith('browser_credential_binding_delete', { binding_id: 'login-1' }));
  });

  it('keeps the draft on a safe server validation failure', async () => {
    mocks.sendRequest.mockImplementation(async (command: string) => command === 'browser_credential_bindings_list'
      ? { bindings: [binding] } : { success: false, error: 'Use vault and item IDs.' });
    const user = userEvent.setup();
    mount();
    await user.click(await screen.findByRole('button', { name: 'Replace Account' }));
    await fillReferences(user);
    await user.click(screen.getByRole('button', { name: 'Save website login' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('Use vault and item IDs.');
    expect(screen.getByLabelText('Password 1Password reference')).toHaveValue(password);
    expect(screen.getByRole('button', { name: 'Save website login' })).toBeEnabled();
  });

  it('does not load a hidden or disconnected panel', async () => {
    const view = mount(false);
    expect(mocks.sendRequest).not.toHaveBeenCalled();
    mocks.ready = false;
    view.change(true);
    expect(screen.getByRole('button', { name: 'Add website login' })).toBeDisabled();
    expect(mocks.sendRequest).not.toHaveBeenCalled();
  });
});

/**
 * The Connecting screen's schedule: a countdown to each check (2, 3, 5,
 * then every 8 seconds), Try now checking at once, a failed or rejected
 * check moving to the next attempt, and an answer stopping it all.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, renderHook } from '@testing-library/react';
import { useRetrySchedule } from '../useRetrySchedule';

let answers: boolean[];
const check = vi.fn(async () => answers.shift() ?? false);

/** Let `seconds` pass, then the check they started settle. */
async function seconds(count: number) {
  await act(async () => {
    vi.advanceTimersByTime(count * 1000);
  });
  await act(async () => {});
}

beforeEach(() => {
  vi.useFakeTimers({ toFake: ['setInterval', 'clearInterval'] });
  answers = [];
  check.mockClear();
});

afterEach(() => {
  vi.useRealTimers();
});

describe('useRetrySchedule', () => {
  it('counts down to each check, waiting 2, 3, 5 and then 8 seconds', async () => {
    const { result } = renderHook(() => useRetrySchedule(check));
    expect(result.current).toMatchObject({ attempt: 1, wait: 2, checking: false });
    await seconds(1);
    expect(result.current.wait).toBe(1);
    await seconds(1);
    expect(check).toHaveBeenCalledTimes(1);
    expect(result.current).toMatchObject({ attempt: 2, wait: 3, checking: false });
    await seconds(3);
    expect(result.current).toMatchObject({ attempt: 3, wait: 5 });
    await seconds(5);
    expect(result.current).toMatchObject({ attempt: 4, wait: 8 });
    await seconds(8);
    await seconds(8);
    expect(result.current).toMatchObject({ attempt: 6, wait: 8 });
    expect(check).toHaveBeenCalledTimes(5);
  });

  it('checks at once on Try now', async () => {
    const { result } = renderHook(() => useRetrySchedule(check));
    await act(async () => {
      result.current.tryNow();
    });
    expect(check).toHaveBeenCalledTimes(1);
    expect(result.current).toMatchObject({ attempt: 2, wait: 3 });
  });

  it('stops once the server answers', async () => {
    answers = [false, true];
    const { result } = renderHook(() => useRetrySchedule(check));
    await seconds(2);
    await seconds(3);
    expect(result.current).toMatchObject({ found: true, checking: false, attempt: 2 });
    await seconds(30);
    expect(check).toHaveBeenCalledTimes(2);
  });

  it('counts a check that fails outright as a failed attempt', async () => {
    check.mockRejectedValueOnce(new Error('network'));
    const { result } = renderHook(() => useRetrySchedule(check));
    await seconds(2);
    expect(result.current).toMatchObject({ attempt: 2, checking: false, found: false });
  });
});

import { act, renderHook } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import { useApiKeyValidation } from '../useApiKeyValidation';

const { apiKeys, toast } = vi.hoisted(() => ({
  apiKeys: {
    validateApiKey: vi.fn(),
    getStoredApiKey: vi.fn(),
    hasStoredKey: vi.fn(),
    removeApiKey: vi.fn(),
    getStoredModels: vi.fn(),
  },
  toast: { success: vi.fn(), error: vi.fn() },
}));

vi.mock('../useApiKeys', () => ({ useApiKeys: () => apiKeys }));
vi.mock('sonner', () => ({ toast }));

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((done) => { resolve = done; });
  return { promise, resolve };
}

describe('useApiKeyValidation request isolation', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    apiKeys.getStoredModels.mockResolvedValue([]);
  });

  it('ignores stored-key results from a previously selected node/provider', async () => {
    const pendingA = deferred<boolean>();
    const pendingB = deferred<boolean>();
    apiKeys.hasStoredKey.mockImplementation((provider: string) => (
      provider === 'provider-a' ? pendingA.promise : pendingB.promise
    ));
    apiKeys.getStoredModels.mockResolvedValue(['model-b']);
    const onSuccess = vi.fn();

    const view = renderHook(
      ({ provider, requestKey }) => useApiKeyValidation({ provider, requestKey, onSuccess }),
      { initialProps: { provider: 'provider-a', requestKey: 'node-a:provider-a' } },
    );

    view.rerender({ provider: 'provider-b', requestKey: 'node-b:provider-b' });
    await act(async () => {
      pendingA.resolve(true);
      await pendingA.promise;
    });
    expect(onSuccess).not.toHaveBeenCalled();

    await act(async () => {
      pendingB.resolve(true);
      await pendingB.promise;
      await Promise.resolve();
    });
    expect(onSuccess).toHaveBeenCalledOnce();
    expect(onSuccess).toHaveBeenCalledWith(['model-b']);
    expect(view.result.current.status).toBe('valid');
  });

  it('ignores validation completion after request identity changes', async () => {
    apiKeys.hasStoredKey.mockResolvedValue(false);
    const pendingValidation = deferred<{ isValid: boolean; models: string[] }>();
    apiKeys.validateApiKey.mockReturnValue(pendingValidation.promise);
    const onSuccess = vi.fn();

    const view = renderHook(
      ({ provider, requestKey }) => useApiKeyValidation({ provider, requestKey, onSuccess }),
      { initialProps: { provider: 'provider-a', requestKey: 'node-a:provider-a' } },
    );
    await act(async () => { await Promise.resolve(); });

    let validation!: Promise<void>;
    act(() => {
      validation = view.result.current.validate('secret');
    });
    view.rerender({ provider: 'provider-b', requestKey: 'node-b:provider-b' });

    await act(async () => {
      pendingValidation.resolve({ isValid: true, models: ['stale-model'] });
      await validation;
    });

    expect(onSuccess).not.toHaveBeenCalled();
    expect(toast.success).not.toHaveBeenCalledWith('API key validated successfully!');
    expect(view.result.current.status).toBe('idle');
  });

  it('reports a credential clear as stale after switching nodes', async () => {
    apiKeys.hasStoredKey.mockResolvedValue(false);
    const pendingClear = deferred<void>();
    apiKeys.removeApiKey.mockReturnValue(pendingClear.promise);

    const view = renderHook(
      ({ provider, requestKey }) => useApiKeyValidation({ provider, requestKey }),
      { initialProps: { provider: 'provider-a', requestKey: 'node-a:provider-a' } },
    );
    await act(async () => { await Promise.resolve(); });

    let clearResult!: Promise<boolean>;
    act(() => {
      clearResult = view.result.current.clear();
    });
    view.rerender({ provider: 'provider-b', requestKey: 'node-b:provider-b' });

    let applied = true;
    await act(async () => {
      pendingClear.resolve();
      applied = await clearResult;
    });

    expect(applied).toBe(false);
    expect(toast.success).not.toHaveBeenCalledWith('API key cleared');
    expect(view.result.current.status).toBe('idle');
  });
});
